// Cap admin WebSocket fanout so a deployment with many admin accounts does
// not incur unbounded DO RPCs on every inbound email. A presence-aware
// implementation (only notifying users with an active stream) would be the
// proper long-term fix; until then this keeps worst-case cost predictable.
export const MAX_ADMIN_FANOUT = 50;
/** Hard cap on DO subrequests generated by one inbound email. */
export const MAX_TOTAL_FANOUT = 50;

/**
 * Compute the deduplicated set of user IDs that should receive a real-time
 * notification for an inbound email: users with an explicit `inbox_permissions`
 * row for the recipient, plus (up to a cap) users with role = "admin".
 *
 * Returns the target list and a flag indicating whether the admin set was
 * truncated by the cap, so the caller can log a warning.
 */
export function computeFanoutTargets(args: {
  permissionUserIds: string[];
  adminUserIds: string[];
  maxAdminFanout?: number;
  maxTotalFanout?: number;
}): {
  userIds: string[];
  adminTruncated: boolean;
  permissionTruncated: boolean;
} {
  const adminCap = args.maxAdminFanout ?? MAX_ADMIN_FANOUT;
  const totalCap = args.maxTotalFanout ?? MAX_TOTAL_FANOUT;
  const uniquePermissions = [...new Set(args.permissionUserIds)];
  const chosenPermissions = uniquePermissions.slice(0, totalCap);
  const userIds = new Set(chosenPermissions);
  const eligibleAdmins = [...new Set(args.adminUserIds)].filter(
    (id) => !userIds.has(id),
  );
  const remaining = Math.max(0, totalCap - userIds.size);
  const chosenAdmins = eligibleAdmins.slice(0, Math.min(adminCap, remaining));
  for (const id of chosenAdmins) userIds.add(id);
  return {
    userIds: [...userIds],
    adminTruncated: chosenAdmins.length < eligibleAdmins.length,
    permissionTruncated: chosenPermissions.length < uniquePermissions.length,
  };
}
